using RideState = pair<int, long long>; // viagens, peso da última viagem

RideState addPerson(RideState currentState, long long personWeight, long long capacity) {
    auto [rideCount, lastRideWeight] = currentState;
    if (lastRideWeight + personWeight <= capacity) return {rideCount, lastRideWeight + personWeight};
    return {rideCount + 1, personWeight};
}

RideState solveElevator(const vector<long long>& personWeights, long long capacity) {
    int personCount = static_cast<int>(personWeights.size());
    if (personCount >= 63) throw invalid_argument("personCount deve ser menor que 63");
    for (long long weight : personWeights) if (weight > capacity) throw invalid_argument("pessoa acima da capacidade");
    size_t subsetCount = size_t(1ULL) << personCount;
    const RideState impossible = {personCount + 1, capacity + 1};
    vector<RideState> bestState(subsetCount, impossible);
    bestState[0] = {1, 0};
    for (size_t mask = 0; mask < subsetCount; ++mask) {
        for (int personIndex = 0; personIndex < personCount; ++personIndex) {
            if (mask & (size_t(1) << personIndex)) continue;
            size_t nextMask = mask | (size_t(1) << personIndex);
            RideState candidate = addPerson(bestState[mask], personWeights[personIndex], capacity);
            bestState[nextMask] = min(bestState[nextMask], candidate);
        }
    }
    return bestState.back();
}
